def transform(g):
    h,w=len(g),len(g[0])
    # bars: horizontal runs of a color != most common, at some row, length>1
    from collections import Counter
    bg=Counter(v for r in g for v in r).most_common(1)[0][0]
    # find marker cells: non-bg cells not part of bars
    bars={}  # (row): list of (start,end,color)
    barcells=set()
    for i,row in enumerate(g):
        j=0
        while j<w:
            if row[j]!=bg:
                k=j
                while k<w and row[k]==row[j]: k+=1
                if k-j>=3:
                    bars.setdefault(i,[]).append((j,k-1,row[j]))
                    for c in range(j,k): barcells.add((i,c))
                j=k
            else: j+=1
    mark=[(i,j,g[i][j]) for i in range(h) for j in range(w) if g[i][j]!=bg and (i,j) not in barcells]
    out=[r[:] for r in g]
    cols=sorted({j for i,j,v in mark}); r0=min(i for i,j,v in mark); r1=max(i for i,j,v in mark)
    mc=mark[0][2]
    # its bar: bar whose span contains marker cols; narrowest
    cands=[(e-s+1,row,s,e,c) for row,(lst) in bars.items() for (s,e,c) in lst if s<=cols[0] and e>=cols[-1]]
    cands.sort()
    row_b,s_b,e_b,c_b=cands[0][1],cands[0][2],cands[0][3],cands[0][4]
    other=[(row,s,e,c) for row,lst in bars.items() for (s,e,c) in lst if not (s<=cols[0] and e>=cols[-1])]
    # other bar: same color if exists
    same=[b for b in other if b[3]==c_b]
    ob=same[0] if same else other[0]
    # stripe: marker cols from marker rows toward its bar
    if row_b < r0: rng=range(row_b+1,r1+1)
    else: rng=range(r0,row_b)
    for i in rng:
        for j in cols:
            out[i][j]= 4 if (i,j) in {(i,j) for i,j,v in mark} else mc
    # stamp at other bar: bbox width, columns of bbox having markers -> mc, all rows
    bw=cols[-1]-cols[0]+1
    has=set(j-cols[0] for i,j,v in mark)
    for i in range(h):
        for d in range(bw):
            if d in has and not (i==ob[0] and ob[1]+d<=ob[2]):
                out[i][ob[1]+d]=mc
    return out

