lib='''def background(grid):
    """The most common color in the grid."""
    from collections import Counter
    return Counter(v for row in grid for v in row).most_common(1)[0][0]

def hbars(grid, min_len=3):
    """Horizontal runs (start, end, color) of length >= min_len of non-background colors, per row, plus the set of their cells."""
    bg = background(grid)
    h, w = len(grid), len(grid[0])
    bars = {}; cells = set()
    for i, row in enumerate(grid):
        j = 0
        while j < w:
            if row[j] != bg:
                k = j
                while k < w and row[k] == row[j]: k += 1
                if k - j >= min_len:
                    bars.setdefault(i, []).append((j, k - 1, row[j]))
                    cells.update((i, c) for c in range(j, k))
                j = k
            else:
                j += 1
    return bars, cells

def marker_cells(grid, barcells):
    """The non-background cells that are not part of any bar, as (row, col, color)."""
    bg = background(grid)
    return [(i, j, grid[i][j]) for i in range(len(grid)) for j in range(len(grid[0]))
            if grid[i][j] != bg and (i, j) not in barcells]

def copy_grid(grid):
    """A fresh copy of the grid."""
    return [row[:] for row in grid]

def project_to_bars(grid, mark=4):
    """Given a grid with two horizontal bars and marker cells: extend each marker column toward the bar containing it (marker cells become `mark`), and stamp the marker's column pattern, offset-preserving, onto the diagonally opposite bar's span for every row."""
    h, w = len(grid), len(grid[0])
    bars, barcells = hbars(grid)
    marks = marker_cells(grid, barcells)
